from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Return the minimum absolute difference between k and a subarray OR.

    At each position, retain the distinct OR values of subarrays ending there.
    Extending a subarray can only add bits, so at most W + 1 values survive
    for W-bit nonnegative integers. Time is O(len(nums) * W), space O(W).
    The input list is not modified.
    """
    if not nums:
        raise ValueError("nums must be nonempty")
    best = abs(nums[0] - k)
    endings = set()
    for number in nums:
        endings = {number} | {value | number for value in endings}
        for value in endings:
            difference = abs(value - k)
            if difference == 0:
                return 0
            if difference < best:
                best = difference
    return best
